public static boolean isPossibleToAllocateMidPagesToKStudents(int[] arr, int K, int mid) {
    int studCount = 1;
    int currPages = 0;
    for (Integer val : arr) {
        currPages += val;
        if (currPages > mid) {
            studCount++;
            currPages = val;
        }
    }

    return studCount <= K;
}
